    switch (self) {
      case EventToUI_Event(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_String(field0, serializer);
      case EventToUI_Rgba(field0: final field0):
        sse_encode_i_32(1, serializer);
        sse_encode_CastedPrimitive_usize(field0, serializer);
      case EventToUI_Texture(field0: final field0, field1: final field1):
        sse_encode_i_32(2, serializer);
        sse_encode_CastedPrimitive_usize(field0, serializer);
        sse_encode_bool(field1, serializer);
      case EventToUI_Cursor(
          id: final id,
          hotx: final hotx,
          hoty: final hoty,
          width: final width,
          height: final height,
          colors: final colors
        ):
        sse_encode_i_32(3, serializer);
        sse_encode_String(id, serializer);
        sse_encode_i_32(hotx, serializer);
        sse_encode_i_32(hoty, serializer);
        sse_encode_i_32(width, serializer);
        sse_encode_i_32(height, serializer);
        sse_encode_list_prim_u_8_strict(colors, serializer);
    }
  }

